-- ==============================================================================
-- SMART DELIVERY OPERATIONS ANALYTICS SYSTEM
-- Self-Contained Staging Data Multi-Row SQL Insert Dump (29,300 Records)
-- Allows Direct Loading into MySQL Workbench without LOAD DATA INFILE Privileges
-- ==============================================================================

USE smart_delivery_analytics;

SET FOREIGN_KEY_CHECKS = 0;
SET SQL_MODE = 'NO_AUTO_VALUE_ON_ZERO';

-- ------------------------------------------------------------------------------
-- Data for stg_customers (1000 records from customers.csv)
-- ------------------------------------------------------------------------------
TRUNCATE TABLE stg_customers;

-- ------------------------------------------------------------------------------
-- Data for stg_customer_behavior (1000 records from customer_behavior.csv)
-- ------------------------------------------------------------------------------
TRUNCATE TABLE stg_customer_behavior;

-- ------------------------------------------------------------------------------
-- Data for stg_delivery_partners (200 records from delivery_partners.csv)
-- ------------------------------------------------------------------------------
TRUNCATE TABLE stg_delivery_partners;

-- ------------------------------------------------------------------------------
-- Data for stg_restaurants (100 records from restaurants.csv)
-- ------------------------------------------------------------------------------
TRUNCATE TABLE stg_restaurants;

-- ------------------------------------------------------------------------------
-- Data for stg_orders (10000 records from orders.csv)
-- ------------------------------------------------------------------------------
TRUNCATE TABLE stg_orders;

-- ------------------------------------------------------------------------------
-- Data for stg_payments (10000 records from payments.csv)
-- ------------------------------------------------------------------------------
TRUNCATE TABLE stg_payments;

-- ------------------------------------------------------------------------------
-- Data for stg_ratings (7000 records from ratings.csv)
-- ------------------------------------------------------------------------------
TRUNCATE TABLE stg_ratings;

SET FOREIGN_KEY_CHECKS = 1;
